head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30100";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil30100.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_65", fn: function(){ return ((dma_yearAssessmentFeeDetail.get("basYy") ?? (() => { throw new Error("unresolved:" + "yearAssessmentFeeDetail.basYy"); })()) > 2012); } }, { id: "tr_66", fn: function(){ return ((dma_yearAssessmentFeeDetail.get("basYy") ?? (() => { throw new Error("unresolved:" + "yearAssessmentFeeDetail.basYy"); })()) > 2012); } }, { id: "c_otherwise_69", fn: function(){ return (!(((dma_yearAssessmentFeeDetail.get("basYy") ?? (() => { throw new Error("unresolved:" + "yearAssessmentFeeDetail.basYy"); })()) > 2012))); } }, { id: "c_when_19", fn: function(){ return ((dma_yearAssessmentFeeDetail.get("anulfeeExmptYn") ?? (() => { throw new Error("unresolved:" + "yearAssessmentFeeDetail.anulfeeExmptYn"); })()) === 'N' || (dma_yearAssessmentFeeDetail.get("anulfeeExmptYn") ?? (() => { throw new Error("unresolved:" + "yearAssessmentFeeDetail.anulfeeExmptYn"); })()) === 'E'); } }, { id: "c_otherwise_85", fn: function(){ return (!(((dma_yearAssessmentFeeDetail.get("anulfeeExmptYn") ?? (() => { throw new Error("unresolved:" + "yearAssessmentFeeDetail.anulfeeExmptYn"); })()) === 'N' || (dma_yearAssessmentFeeDetail.get("anulfeeExmptYn") ?? (() => { throw new Error("unresolved:" + "yearAssessmentFeeDetail.anulfeeExmptYn"); })()) === 'E'))); } }, { id: "c_when_17", fn: function(){ return ((dma_yearAssessmentFeeDetail.get("anulfeeFinalYn") ?? (() => { throw new Error("unresolved:" + "yearAssessmentFeeDetail.anulfeeFinalYn"); })()) === 'Y'); } }, { id: "c_otherwise_104", fn: function(){ return (!(((dma_yearAssessmentFeeDetail.get("anulfeeFinalYn") ?? (() => { throw new Error("unresolved:" + "yearAssessmentFeeDetail.anulfeeFinalYn"); })()) === 'Y'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb2", fn: function () { return String(dma_yearAssessmentFeeDetail.get("basYy")) + "년"; } },
        { childId: "__rb4", fn: function () { return String(dma_yearAssessmentFeeDetail.get("stkcertAnulfee")) + " 원"; } },
        { childId: "__rb5", fn: function () { return String(dma_yearAssessmentFeeDetail.get("benfcertAnulfee")) + " 원"; } },
        { childId: "__rb6", fn: function () { return String(dma_yearAssessmentFeeDetail.get("etfAnulfee")) + " 원"; } },
        { childId: "__rb7", fn: function () { return String(dma_yearAssessmentFeeDetail.get("subsrghtAnulfee")) + " 원"; } },
        { childId: "__rb8", fn: function () { return String(dma_yearAssessmentFeeDetail.get("elwAnulfee")) + " 원"; } },
        { childId: "__rb9", fn: function () { return String(dma_yearAssessmentFeeDetail.get("etnAnulfee")) + " 원"; } },
        { childId: "__rb10", fn: function () { return String(dma_yearAssessmentFeeDetail.get("anulfeeTotal")) + " 원"; } },
        { childId: "__rb11", fn: function () { return String(dma_yearAssessmentFeeDetail.get("avgMktCap")) + " 원"; } },
        { childId: "__rb12", fn: function () { return String(dma_yearAssessmentFeeDetail.get("cap")) + " 원"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_SearchDetail_onclick
 * @description 「인쇄」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_SearchDetail_onclick = function(e){
    try {
        scwin.searchDetail('' + dma_yearAssessmentFeeDetail.get("ldMktTpCd") + '','' + dma_yearAssessmentFeeDetail.get("isurCd") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30100.btn_SearchDetail_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_goTab1
 * @description go Tab1 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goTab1 = async function () {
    const sbmOptions = {
        id: "tx_fn_goTab1",
        method: "post",
        action: "/issue/yearAssessmentFee.do",
        ref: "dma_goTab1Req",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goTab2
 * @description go Tab2 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goTab2 = async function () {
    const sbmOptions = {
        id: "tx_fn_goTab2",
        method: "post",
        action: "/issue/yearAsmtFeeReceipt.do",
        ref: "dma_goTab2Req",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_SearchDetail
 * @description Search Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchDetail = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_SearchDetailReq") ? $c.util.getComponent("dma_SearchDetailReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name searchDetail
 * @description search Detail 처리
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} isurCd isurCd
 * @returns {void}
 * @hidden N
 */
scwin.searchDetail = function (ldMktTpCd, isurCd) {
    let rexName;
    let dataLocation = "";
    let mktGubun = "";
    if (ldMktTpCd === "유가증권시장") {
        mktGubun = "1";
        dataLocation = "/issue/reportPrint.do?method=searchYearAssessmentFeeNewGet&reportDiv=1&mktGubun=" + mktGubun + "&isurCd=" + isurCd;
        if ('' + dma_yearAssessmentFeeDetail.get("basYy") + '' < '2013') {
            rexName = "RLDFIL00007";
        } else {
            if ('' + dma_yearAssessmentFeeDetail.get("basYy") + '' >= '2013') {
                rexName = "RLDFIL00007_1";
            }
        }
    } else {
        if (ldMktTpCd === "코넥스시장") {
            mktGubun = "6";
            dataLocation = "/issue/reportPrint.do?method=searchYearAssessmentFeeNewGet&reportDiv=6&mktGubun=" + mktGubun + "&isurCd=" + isurCd;
            rexName = "RLDFIL00043";
        } else {
            mktGubun = "2";
            dataLocation = "/issue/reportPrint.do?method=searchYearAssessmentFeeNewGet&reportDiv=2&mktGubun=" + mktGubun + "&isurCd=" + isurCd;
            if ('' + dma_yearAssessmentFeeDetail.get("basYy") + '' < '2013') {
                rexName = "RLDFIL00008";
            } else {
                if ('' + dma_yearAssessmentFeeDetail.get("basYy") + '' >= '2013') {
                    rexName = "RLDFIL00008_1";
                }
            }
        }
    }
    $.ajax({ type: "POST", async: false, url: dataLocation, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const form = (document.newReportForm || { elements: [] });
                $c.util.getComponent('dma_SearchDetailReq').set('nsend', result.send);
                $c.util.getComponent('dma_SearchDetailReq').set('nbasYy', result.basYy);
                $c.util.getComponent('dma_SearchDetailReq').set('nanulfeePayMethdDsc', result.anulfeePayMethdDsc);
                $c.util.getComponent('dma_SearchDetailReq').set('nchgEmp', result.chgEmp);
                $c.util.getComponent('dma_SearchDetailReq').set('ngenealChief', result.genealChief);
                $c.util.getComponent('dma_SearchDetailReq').set('nemail', result.email);
                $c.util.getComponent('dma_SearchDetailReq').set('npassage', result.passage);
                $c.util.getComponent('dma_SearchDetailReq').set('nanulfeeNotiImpostNo', result.anulfeeNotiImpostNo);
                $c.util.getComponent('dma_SearchDetailReq').set('nbank', result.bank);
                if (result.payDeadlineDd) {
                    let sub_printDate = result.payDeadlineDd;
                    let sub_printDate_Y = sub_printDate.substring(0, 4);
                    let sub_printDate_M = sub_printDate.substring(4, 6);
                    let sub_printDate_D = sub_printDate.substring(6, 8);
                    $c.util.getComponent('dma_SearchDetailReq').set('npayDeadlineDd', sub_printDate_Y + '년 ' + sub_printDate_M + '월' + sub_printDate_D + '일까지 납부');
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('npayDeadlineDd', result.payDeadlineDd);
                }
                if (result.stkcertAnulfee) {
                    let len_stkcertAnulfee, point_stkcertAnulfee, comma_plus_stkcertAnulfee;
                    let simple_stkcertAnulfee = result.stkcertAnulfee;
                    len_stkcertAnulfee = simple_stkcertAnulfee.length;
                    simple_stkcertAnulfee = simple_stkcertAnulfee + "";
                    point_stkcertAnulfee = len_stkcertAnulfee % 3;
                    comma_plus_stkcertAnulfee = simple_stkcertAnulfee.substring(0, point_stkcertAnulfee);
                    while (point_stkcertAnulfee < len_stkcertAnulfee) {
                        if (comma_plus_stkcertAnulfee !== "") {
                            comma_plus_stkcertAnulfee += ",";
                        }
                        comma_plus_stkcertAnulfee += simple_stkcertAnulfee.substring(point_stkcertAnulfee, point_stkcertAnulfee + 3);
                        point_stkcertAnulfee += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('nstkcertAnulfee', comma_plus_stkcertAnulfee);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nstkcertAnulfee', result.stkcertAnulfee);
                }
                if (result.benfcertAnulfee) {
                    let len_benfcertAnulfee, point_benfcertAnulfee, comma_plus_benfcertAnulfee;
                    let simple_benfcertAnulfee = result.benfcertAnulfee;
                    len_benfcertAnulfee = simple_benfcertAnulfee.length;
                    simple_benfcertAnulfee = simple_benfcertAnulfee + "";
                    point_benfcertAnulfee = len_benfcertAnulfee % 3;
                    comma_plus_benfcertAnulfee = simple_benfcertAnulfee.substring(0, point_benfcertAnulfee);
                    while (point_benfcertAnulfee < len_benfcertAnulfee) {
                        if (comma_plus_benfcertAnulfee !== "") {
                            comma_plus_benfcertAnulfee += ",";
                        }
                        comma_plus_benfcertAnulfee += simple_benfcertAnulfee.substring(point_benfcertAnulfee, point_benfcertAnulfee + 3);
                        point_benfcertAnulfee += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('nbenfcertAnulfee', comma_plus_benfcertAnulfee);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nbenfcertAnulfee', result.benfcertAnulfee);
                }
                if (result.subsrghtAnulfee) {
                    let len_subsrghtAnulfee, point_subsrghtAnulfee, comma_plus_subsrghtAnulfee;
                    let simple_subsrghtAnulfee = result.subsrghtAnulfee;
                    len_subsrghtAnulfee = simple_subsrghtAnulfee.length;
                    simple_subsrghtAnulfee = simple_subsrghtAnulfee + "";
                    point_subsrghtAnulfee = len_subsrghtAnulfee % 3;
                    comma_plus_subsrghtAnulfee = simple_subsrghtAnulfee.substring(0, point_subsrghtAnulfee);
                    while (point_subsrghtAnulfee < len_subsrghtAnulfee) {
                        if (comma_plus_subsrghtAnulfee !== "") {
                            comma_plus_subsrghtAnulfee += ",";
                        }
                        comma_plus_subsrghtAnulfee += simple_subsrghtAnulfee.substring(point_subsrghtAnulfee, point_subsrghtAnulfee + 3);
                        point_subsrghtAnulfee += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('nsubsrghtAnulfee', comma_plus_subsrghtAnulfee);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nsubsrghtAnulfee', result.subsrghtAnulfee);
                }
                if (result.elwAnulfee) {
                    let len_elwAnulfee, point_elwAnulfee, comma_plus_elwAnulfee;
                    let simple_elwAnulfee = result.elwAnulfee;
                    len_elwAnulfee = simple_elwAnulfee.length;
                    simple_elwAnulfee = simple_elwAnulfee + "";
                    point_elwAnulfee = len_elwAnulfee % 3;
                    comma_plus_elwAnulfee = simple_elwAnulfee.substring(0, point_elwAnulfee);
                    while (point_elwAnulfee < len_elwAnulfee) {
                        if (comma_plus_elwAnulfee !== "") {
                            comma_plus_elwAnulfee += ",";
                        }
                        comma_plus_elwAnulfee += simple_elwAnulfee.substring(point_elwAnulfee, point_elwAnulfee + 3);
                        point_elwAnulfee += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('nelwAnulfee', comma_plus_elwAnulfee);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nelwAnulfee', result.elwAnulfee);
                }
                if (result.etnAnulfee) {
                    let len_etnAnulfee, point_etnAnulfee, comma_plus_etnAnulfee;
                    let simple_etnAnulfee = result.etnAnulfee;
                    len_etnAnulfee = simple_etnAnulfee.length;
                    simple_etnAnulfee = simple_etnAnulfee + "";
                    point_etnAnulfee = len_etnAnulfee % 3;
                    comma_plus_etnAnulfee = simple_etnAnulfee.substring(0, point_etnAnulfee);
                    while (point_etnAnulfee < len_etnAnulfee) {
                        if (comma_plus_etnAnulfee !== "") {
                            comma_plus_etnAnulfee += ",";
                        }
                        comma_plus_etnAnulfee += simple_etnAnulfee.substring(point_etnAnulfee, point_etnAnulfee + 3);
                        point_etnAnulfee += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('netnAnulfee', comma_plus_etnAnulfee);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('netnAnulfee', result.etnAnulfee);
                }
                if (result.anulfeeTotal) {
                    let len_anulfeeTotal, point_anulfeeTotal, comma_plus_anulfeeTotal;
                    let simple_anulfeeTotal = result.anulfeeTotal;
                    len_anulfeeTotal = simple_anulfeeTotal.length;
                    simple_anulfeeTotal = simple_anulfeeTotal + "";
                    point_anulfeeTotal = len_anulfeeTotal % 3;
                    comma_plus_anulfeeTotal = simple_anulfeeTotal.substring(0, point_anulfeeTotal);
                    while (point_anulfeeTotal < len_anulfeeTotal) {
                        if (comma_plus_anulfeeTotal !== "") {
                            comma_plus_anulfeeTotal += ",";
                        }
                        comma_plus_anulfeeTotal += simple_anulfeeTotal.substring(point_anulfeeTotal, point_anulfeeTotal + 3);
                        point_anulfeeTotal += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('nanulfeeTotal', comma_plus_anulfeeTotal);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nanulfeeTotal', result.anulfeeTotal);
                }
                if (result.cap) {
                    let len_cap, point_cap, comma_plus_cap;
                    let simple_cap = result.cap;
                    len_cap = simple_cap.length;
                    simple_cap = simple_cap + "";
                    point_cap = len_cap % 3;
                    comma_plus_cap = simple_cap.substring(0, point_cap);
                    while (point_cap < len_cap) {
                        if (comma_plus_cap !== "") {
                            comma_plus_cap += ",";
                        }
                        comma_plus_cap += simple_cap.substring(point_cap, point_cap + 3);
                        point_cap += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('ncap', comma_plus_cap);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('ncap', result.cap);
                }
                if (result.avgMktCap) {
                    let rounds_avgMktCap = Math.round(result.avgMktCap);
                    let len_avgMktCap, point_avgMktCap, comma_plus_avgMktCap;
                    len_avgMktCap = String(rounds_avgMktCap).length;
                    rounds_avgMktCap = rounds_avgMktCap + "";
                    point_avgMktCap = len_avgMktCap % 3;
                    comma_plus_avgMktCap = rounds_avgMktCap.substring(0, point_avgMktCap);
                    while (point_avgMktCap < len_avgMktCap) {
                        if (comma_plus_avgMktCap !== "") {
                            comma_plus_avgMktCap += ",";
                        }
                        comma_plus_avgMktCap += rounds_avgMktCap.substring(point_avgMktCap, point_avgMktCap + 3);
                        point_avgMktCap += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('navgMktCap', comma_plus_avgMktCap);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('navgMktCap', result.avgMktCap);
                }
                if (result.paySnulfee) {
                    let len_paySnulfee, point_paySnulfee, comma_plus_paySnulfee;
                    let simple_paySnulfee = result.paySnulfee;
                    len_paySnulfee = simple_paySnulfee.length;
                    simple_paySnulfee = simple_paySnulfee + "";
                    point_paySnulfee = len_paySnulfee % 3;
                    comma_plus_paySnulfee = simple_paySnulfee.substring(0, point_paySnulfee);
                    while (point_paySnulfee < len_paySnulfee) {
                        if (comma_plus_paySnulfee !== "") {
                            comma_plus_paySnulfee += ",";
                        }
                        comma_plus_paySnulfee += simple_paySnulfee.substring(point_paySnulfee, point_paySnulfee + 3);
                        point_paySnulfee += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('npaySnulfee', comma_plus_paySnulfee);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('npaySnulfee', result.paySnulfee);
                }
                $c.util.getComponent('dma_SearchDetailReq').set('nremk', result.remk);
                if (result.anulfeeEnforceDd) {
                    sub_printDate = result.anulfeeEnforceDd;
                    sub_printDate_Y = sub_printDate.substring(0, 4);
                    sub_printDate_M = sub_printDate.substring(4, 6);
                    sub_printDate_D = sub_printDate.substring(6, 8);
                    $c.util.getComponent('dma_SearchDetailReq').set('nanulfeeEnforceDd', sub_printDate_Y + '. ' + sub_printDate_M + '. ' + sub_printDate_D);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nanulfeeEnforceDd', result.anulfeeEnforceDd);
                }
                $c.util.getComponent('dma_SearchDetailReq').set('nTempleteCd', rexName);
                await scwin.tx_fn_SearchDetail();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
};

/**
 * @method
 * @name goTab1
 * @description go Tab1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goTab1 = async function () {
    const frm = (document.frm1 || { elements: [] });
    frm.action = 'yearAssessmentFee.do';
    $c.util.getComponent('dma_SearchDetailReq').set('method', 'searchYearAssessmentFee');
    const nr = await scwin.tx_fn_goTab1();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30104/jldfil30104.xml", { "method": 'searchYearAssessmentFee' });
    }
};

/**
 * @method
 * @name goTab2
 * @description go Tab2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
